// compile.js - Compiles all slide modules into final presentation
const pptxgen = require('pptxgenjs');
const pres = new pptxgen();

pres.layout = 'LAYOUT_16x9';
pres.title = 'SmolVLM: Redefining Small and Efficient Multimodal Models';
pres.author = 'Hugging Face & Stanford University';

const theme = {
  primary: "000814",   // Deep dark blue
  secondary: "001d3d", // Dark navy
  accent: "003566",    // Mid blue
  light: "ffc300",     // Golden yellow accent
  bg: "000814"         // Dark background
};

// Load and create all 9 slides
for (let i = 1; i <= 9; i++) {
  const num = String(i).padStart(2, '0');
  const slideModule = require(`./slide-${num}.js`);
  slideModule.createSlide(pres, theme);
}

pres.writeFile({ fileName: './output/final_deck.pptx' })
  .then(() => {
    console.log('Presentation created successfully: ./output/final_deck.pptx');
  })
  .catch(err => {
    console.error('Error creating presentation:', err);
  });

