const { LAYOUT_16x9 } = require("pres");
const { createSlide, Text, Rectangle, Image } = require("pres");
const pres = require("pres");

const theme = {
  primary: "000814",
  secondary: "001d3d",
  accent: "003566",
  light: "ffc300",
  bg: "000814"
};

function createSlide(pres, theme) {
  const slide = pres.createSlide({ background: theme.bg, layout: LAYOUT_16x9 });

  // Title
  slide.addText(
    "Aggressive Pixel Shuffle (r=4) Cuts Visual Tokens 16\u00D7 for Small Models",
    {
      x: 0.5,
      y: 0.3,
      w: 9,
      h: 0.6,
      fontSize: 22,
      fontFace: "Arial",
      color: theme.light,
      bold: true
    }
  );

  // Subtitle
  slide.addText("Finding 2: Pixel Shuffle Mechanism", {
    x: 0.5,
    y: 0.85,
    w: 4,
    h: 0.3,
    fontSize: 14,
    fontFace: "Arial",
    color: theme.light,
    bold: true
  });

  // Left section - Visual diagram of pixel shuffle
  // Container box for the diagram
  slide.addShape("rect", {
    x: 0.5,
    y: 1.3,
    w: 4.5,
    h: 3.4,
    fill: theme.secondary,
    line: { color: theme.accent, width: 1 }
  });

  slide.addText("Pixel Shuffle: Spatial \u2192 Channel Rearrangement", {
    x: 0.6,
    y: 1.35,
    w: 4.3,
    h: 0.3,
    fontSize: 11,
    fontFace: "Arial",
    color: theme.light,
    bold: true
  });

  // Visual representation: 4x4 grid becoming 1
  // Draw 4x4 pixel grid on left
  const patchStartX = 0.8;
  const patchStartY = 1.85;
  const cellSize = 0.35;
  const cellGap = 0.05;

  // Draw the 4x4 grid of colored cells
  const colors4x4 = [
    ["ff6b6b", "4ecdc4", "45b7d1", "96ceb4"],
    ["ffeaa7", "dfe6e9", "fd79a8", "a29bfe"],
    ["6c5ce7", "00b894", "e17055", "fdcb6e"],
    ["74b9ff", "a55eea", "26de81", "fc5c65"]
  ];

  for (let row = 0; row < 4; row++) {
    for (let col = 0; col < 4; col++) {
      slide.addShape("rect", {
        x: patchStartX + col * (cellSize + cellGap),
        y: patchStartY + row * (cellSize + cellGap),
        w: cellSize,
        h: cellSize,
        fill: colors4x4[row % colors4x4.length][col],
        line: { color: theme.accent, width: 0.5 }
      });
    }
  }

  // Arrow pointing right
  slide.addText("\u2192", {
    x: 2.4,
    y: 2.3,
    w: 0.5,
    h: 0.5,
    fontSize: 28,
    fontFace: "Arial",
    color: theme.light,
    align: "center",
    valign: "middle"
  });

  // Label for arrow
  slide.addText("Pixel\nShuffle", {
    x: 2.3,
    y: 2.85,
    w: 0.7,
    h: 0.5,
    fontSize: 9,
    fontFace: "Arial",
    color: theme.light,
    align: "center"
  });

  // Single channel output on right
  const outputX = 3.1;
  slide.addShape("rect", {
    x: outputX,
    y: patchStartY,
    w: cellSize,
    h: cellSize,
    fill: theme.light,
    line: { color: theme.light, width: 2 }
  });

  slide.addText("1\nChannel", {
    x: outputX - 0.2,
    y: patchStartY + 0.55,
    w: 0.8,
    h: 0.5,
    fontSize: 9,
    fontFace: "Arial",
    color: "ffffff",
    align: "center"
  });

  // Token reduction formula
  slide.addShape("rect", {
    x: 0.8,
    y: 3.85,
    w: 3.9,
    h: 0.55,
    fill: theme.accent
  });
