// slide-01.js - Cover Slide: SmolVLM
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'cover',
  index: 1,
  title: 'SmolVLM: Redefining Small and Efficient Multimodal Models'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // --- Visual Element: Abstract Efficient AI/Edge Computing ---
  // Represents a small efficient chip/processor with radiating connections

  // Large decorative circle (outer glow) - top right area
  slide.addShape(pres.shapes.OVAL, {
    x: 6.5, y: 0.8, w: 3.5, h: 3.5,
    fill: { color: theme.secondary, transparency: 60 }
  });

  // Medium circle (mid layer)
  slide.addShape(pres.shapes.OVAL, {
    x: 7.2, y: 1.5, w: 2.2, h: 2.2,
    fill: { color: theme.accent, transparency: 50 }
  });

  // Small core circle (processor core)
  slide.addShape(pres.shapes.OVAL, {
    x: 7.85, y: 2.15, w: 0.9, h: 0.9,
    fill: { color: theme.light }
  });

  // Connection lines radiating from core
  // Top-right diagonal
  slide.addShape(pres.shapes.LINE, {
    x: 8.3, y: 2.1, w: 1.2, h: -0.6,
    line: { color: theme.light, width: 1.5 }
  });
  slide.addShape(pres.shapes.OVAL, {
    x: 9.4, y: 1.35, w: 0.2, h: 0.2,
    fill: { color: theme.light }
  });

  // Right horizontal
  slide.addShape(pres.shapes.LINE, {
    x: 8.75, y: 2.6, w: 0.8, h: 0,
    line: { color: theme.light, width: 1.5 }
  });
  slide.addShape(pres.shapes.OVAL, {
    x: 9.5, y: 2.45, w: 0.2, h: 0.2,
    fill: { color: theme.light }
  });

  // Bottom-right diagonal
  slide.addShape(pres.shapes.LINE, {
    x: 8.3, y: 3.05, w: 1.2, h: 0.6,
    line: { color: theme.light, width: 1.5 }
  });
  slide.addShape(pres.shapes.OVAL, {
    x: 9.4, y: 3.55, w: 0.2, h: 0.2,
    fill: { color: theme.light }
  });

  // Bottom horizontal
  slide.addShape(pres.shapes.LINE, {
    x: 8.0, y: 3.5, w: 0, h: 0.5,
    line: { color: theme.light, width: 1.5 }
  });
  slide.addShape(pres.shapes.OVAL, {
    x: 7.85, y: 3.95, w: 0.2, h: 0.2,
    fill: { color: theme.light }
  });

  // Left connection
  slide.addShape(pres.shapes.LINE, {
    x: 7.4, y: 2.6, w: -0.6, h: 0,
    line: { color: theme.light, width: 1.5 }
  });
  slide.addShape(pres.shapes.OVAL, {
    x: 6.7, y: 2.45, w: 0.2, h: 0.2,
    fill: { color: theme.light }
  });

  // Small floating dots suggesting distributed edge nodes
  slide.addShape(pres.shapes.OVAL, {
    x: 6.0, y: 1.0, w: 0.15, h: 0.15,
    fill: { color: theme.light, transparency: 30 }
  });
  slide.addShape(pres.shapes.OVAL, {
    x: 5.5, y: 2.0, w: 0.12, h: 0.12,
    fill: { color: theme.light, transparency: 50 }
  });
  slide.addShape(pres.shapes.OVAL, {
    x: 6.2, y: 4.0, w: 0.15, h: 0.15,
    fill: { color: theme.light, transparency: 30 }
  });
  slide.addShape(pres.shapes.OVAL, {
    x: 5.8, y: 3.0, w: 0.1, h: 0.1,
    fill: { color: theme.light, transparency: 60 }
  });

  // --- Text Content ---

  // Main Title
  slide.addText("SmolVLM: Redefining Small and Efficient Multimodal Models", {
    x: 0.5, y: 1.8, w: 6.2, h: 1.5,
    fontSize: 36, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "left", valign: "middle"
  });

  // Subtitle - Institutions
  slide.addText("Hugging Face & Stanford University", {
    x: 0.5, y: 3.4, w: 6, h: 0.5,
    fontSize: 20, fontFace: "Arial",
    color: theme.light,
    align: "left", valign: "middle"
  });

  // Decorative line under subtitle
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.0, w: 2.5, h: 0.04,
    fill: { color: theme.light }
  });

  // arXiv tagline
  slide.addText("arXiv:2504.05299", {
    x: 0.5, y: 4.3, w: 3, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: theme.accent,
    align: "left", valign: "middle"
  });

  // Small accent bar on left edge
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.08, h: 5.625,
    fill: { color: theme.light }
  });

  return slide;
}

// Standalone preview
if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "000814",
    secondary: "001d3d",
    accent: "003566",
    light: "ffc300",
    bg: "000814"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "/app/slides/slide-01-preview.pptx" });
  console.log("Preview saved to /app/slides/slide-01-preview.pptx");
}

module.exports = { createSlide, slideConfig };

