// slide-05.js - Content: Pixel Shuffle Token Compression
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 5,
  title: 'Aggressive Pixel Shuffle (r=4) Cuts Visual Tokens 16× for Small Models'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Aggressive Pixel Shuffle (r=4) Cuts Visual Tokens 16× for Small Models", {
    x: 0.5, y: 0.3, w: 9, h: 0.6,
    fontSize: 22, fontFace: "Arial",
    color: theme.light, bold: true
  });

  // Subtitle
  slide.addText("Finding 2: Pixel Shuffle Mechanism", {
    x: 0.5, y: 0.85, w: 4, h: 0.3,
    fontSize: 14, fontFace: "Arial",
    color: theme.light, bold: true
  });

  // Left section - Visual diagram of pixel shuffle
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.3, w: 4.5, h: 3.4,
    fill: { color: theme.secondary },
    line: { color: theme.accent, width: 1 }
  });

  slide.addText("Pixel Shuffle: Spatial → Channel Rearrangement", {
    x: 0.6, y: 1.35, w: 4.3, h: 0.3,
    fontSize: 11, fontFace: "Arial",
    color: theme.light, bold: true
  });

  // Visual: 4x4 pixel grid becoming 1
  const patchStartX = 0.8;
  const patchStartY = 1.85;
  const cellSize = 0.35;
  const cellGap = 0.05;

  const colors4x4 = [
    ["ff6b6b", "4ecdc4", "45b7d1", "96ceb4"],
    ["ffeaa7", "dfe6e9", "fd79a8", "a29bfe"],
    ["6c5ce7", "00b894", "e17055", "fdcb6e"],
    ["74b9ff", "a55eea", "26de81", "fc5c65"]
  ];

  for (let row = 0; row < 4; row++) {
    for (let col = 0; col < 4; col++) {
      slide.addShape(pres.shapes.RECTANGLE, {
        x: patchStartX + col * (cellSize + cellGap),
        y: patchStartY + row * (cellSize + cellGap),
        w: cellSize, h: cellSize,
        fill: { color: colors4x4[row % colors4x4.length][col] },
        line: { color: theme.accent, width: 0.5 }
      });
    }
  }

  // Arrow
  slide.addText("→", {
    x: 2.4, y: 2.3, w: 0.5, h: 0.5,
    fontSize: 28, fontFace: "Arial",
    color: theme.light, align: "center", valign: "middle"
  });

  slide.addText("Pixel\nShuffle", {
    x: 2.3, y: 2.85, w: 0.7, h: 0.5,
    fontSize: 9, fontFace: "Arial",
    color: theme.light, align: "center"
  });

  // Single channel output
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 3.1, y: patchStartY, w: cellSize, h: cellSize,
    fill: { color: theme.light },
    line: { color: theme.light, width: 2 }
  });

  slide.addText("1\nChannel", {
    x: 3.1 - 0.2, y: patchStartY + 0.55, w: 0.8, h: 0.5,
    fontSize: 9, fontFace: "Arial",
    color: "FFFFFF", align: "center"
  });

  // Token reduction formula
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.8, y: 3.85, w: 3.9, h: 0.55,
    fill: { color: theme.accent }
  });
  slide.addText("Tokens Reduced = r²  (r=4 → 16× reduction)", {
    x: 0.8, y: 3.85, w: 3.9, h: 0.55,
    fontSize: 13, fontFace: "Arial",
    color: "FFFFFF", align: "center", valign: "middle", bold: true
  });

  // Right section - Image
  slide.addImage({ path: "/app/slides/imgs/figure_6.jpg", x: 5.2, y: 1.2, w: 4.3, h: 2.2 });

  slide.addText("Figure 6: Pixel shuffle visualization", {
    x: 5.2, y: 3.45, w: 4.3, h: 0.25,
    fontSize: 9, fontFace: "Arial",
    color: "aaaaaa", align: "center"
  });

  // r=2 box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.2, y: 3.8, w: 2.0, h: 1.0,
    fill: { color: theme.secondary },
    line: { color: theme.accent, width: 1 }
  });

  slide.addText("r = 2", {
    x: 5.2, y: 3.85, w: 2.0, h: 0.35,
    fontSize: 14, fontFace: "Arial",
    color: theme.light, bold: true, align: "center"
  });

  slide.addText("4× reduction", {
    x: 5.2, y: 4.2, w: 2.0, h: 0.25,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", align: "center"
  });

  slide.addText("Large models", {
    x: 5.2, y: 4.5, w: 2.0, h: 0.25,
    fontSize: 10, fontFace: "Arial",
    color: "aaaaaa", align: "center"
  });

  // r=4 box (highlighted)
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.4, y: 3.8, w: 2.1, h: 1.0,
    fill: { color: theme.accent },
    line: { color: theme.light, width: 2 }
  });

  slide.addText("r = 4", {
    x: 7.4, y: 3.85, w: 2.1, h: 0.35,
    fontSize: 14, fontFace: "Arial",
    color: theme.light, bold: true, align: "center"
  });

  slide.addText("16× reduction", {
    x: 7.4, y: 4.2, w: 2.1, h: 0.25,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", align: "center"
  });

  slide.addText("Small VLMs", {
    x: 7.4, y: 4.5, w: 2.1, h: 0.25,
    fontSize: 10, fontFace: "Arial",
    color: "FFFFFF", align: "center"
  });

  // Key benefit box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.55, w: 4.5, h: 0.8,
    fill: { color: theme.secondary },
    line: { color: theme.light, width: 1 }
  });

  slide.addText("KEY BENEFIT FOR SMALL VLMs", {
    x: 0.6, y: 4.6, w: 4.3, h: 0.3,
    fontSize: 10, fontFace: "Arial",
    color: theme.light, bold: true
  });

  slide.addText("Eases attention overhead by cutting tokens 16×, enabling efficient processing without sacrificing quality.", {
    x: 0.6, y: 4.9, w: 4.3, h: 0.4,
    fontSize: 11, fontFace: "Arial",
    color: "FFFFFF"
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.light }
  });
  slide.addText("5", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: theme.bg, bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

// Standalone preview
if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "000814",
    secondary: "001d3d",
    accent: "003566",
    light: "ffc300",
    bg: "000814"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "/app/slides/slide-05-preview.pptx" });
  console.log("Preview saved to /app/slides/slide-05-preview.pptx");
}

module.exports = { createSlide, slideConfig };

