const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'summary',
  index: 9,
  title: 'Key Takeaways: Design Principles for Efficient Multimodal Models'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Key Takeaways: Design Principles for Efficient Multimodal Models", {
    x: 0.5, y: 0.3, w: 9, h: 0.6,
    fontSize: 26, fontFace: "Arial",
    color: theme.light, bold: true, align: "left", valign: "middle"
  });

  // Decorative accent line under title
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 0.9, w: 2.5, h: 0.05,
    fill: { color: theme.light }
  });

  const takeaways = [
    { num: "1", text: "Balance encoder-LM compute: smaller encoders outperform larger ones for compact VLMs" },
    { num: "2", text: "Extend context length: 16K tokens unlocks higher image resolution" },
    { num: "3", text: "Use aggressive token compression: r=4 (16× reduction) for small models" },
    { num: "4", text: "Sub-1GB inference is achievable: SmolVLM-256M runs at 0.8GB" },
    { num: "5", text: "Fully open-source: All models, data, code, and mobile app released" }
  ];

  const startY = 1.2;
  const itemHeight = 0.75;
  const colWidth = 4.2;

  // Left column takeaways (1-3)
  takeaways.slice(0, 3).forEach((item, idx) => {
    const y = startY + idx * itemHeight;

    slide.addShape(pres.shapes.OVAL, {
      x: 0.5, y: y + 0.08, w: 0.4, h: 0.4,
      fill: { color: theme.light }
    });

    slide.addText("\u2713", {
      x: 0.5, y: y + 0.08, w: 0.4, h: 0.4,
      fontSize: 18, fontFace: "Arial",
      color: theme.bg, bold: true,
      align: "center", valign: "middle"
    });

    slide.addText(item.text, {
      x: 1.05, y: y, w: colWidth, h: 0.55,
      fontSize: 13, fontFace: "Arial",
      color: "FFFFFF", align: "left", valign: "middle"
    });
  });

  // Right column takeaways (4-5)
  takeaways.slice(3, 5).forEach((item, idx) => {
    const y = startY + idx * itemHeight;

    slide.addShape(pres.shapes.OVAL, {
      x: 5.1, y: y + 0.08, w: 0.4, h: 0.4,
      fill: { color: theme.light }
    });

    slide.addText("\u2713", {
      x: 5.1, y: y + 0.08, w: 0.4, h: 0.4,
      fontSize: 18, fontFace: "Arial",
      color: theme.bg, bold: true,
      align: "center", valign: "middle"
    });

    slide.addText(item.text, {
      x: 5.65, y: y, w: colWidth, h: 0.55,
      fontSize: 13, fontFace: "Arial",
      color: "FFFFFF", align: "left", valign: "middle"
    });
  });

  // Decorative vertical divider
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 4.95, y: 1.3, w: 0.03, h: 2.0,
    fill: { color: theme.accent }
  });

  // Bottom closing statement banner
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.2, w: 9, h: 0.8,
    fill: { color: theme.secondary },
    line: { color: theme.light, width: 1.5 }
  });

  slide.addText("SmolVLM redefines what's possible for on-device multimodal AI", {
    x: 0.5, y: 4.2, w: 9, h: 0.8,
    fontSize: 20, fontFace: "Arial",
    color: theme.light, bold: true,
    align: "center", valign: "middle", italic: true
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.light }
  });
  slide.addText("9", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: theme.bg, bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

// Standalone preview
if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "000814",
    secondary: "001d3d",
    accent: "003566",
    light: "ffc300",
